
// Almacenamiento seguro: separa persistencia local, recuperación de sesión y memoria.
const storage=(()=>{
  const memory=new Map();
  let nativeStore=null,sessionStore=null,lastError=null;
  const probe=(candidate,key)=>{try{candidate.setItem(key,'1');candidate.removeItem(key);return candidate;}catch(error){lastError=error;return null;}};
  const read=(store,key)=>{if(!store)return null;try{return store.getItem(String(key));}catch(error){lastError=error;return null;}};
  const write=(store,key,value)=>{if(!store)return{ok:false,verified:false,error:lastError};try{const k=String(key),v=String(value);store.setItem(k,v);const verified=store.getItem(k)===v;return{ok:verified,verified,error:verified?null:new Error('La lectura de verificación no coincide')};}catch(error){lastError=error;return{ok:false,verified:false,error};}};
  try{nativeStore=probe(window.localStorage,'__na_storage_test__');}catch(error){lastError=error;}
  try{sessionStore=probe(window.sessionStorage,'__na_session_test__');}catch(error){lastError=error;}
  return{
    getItem(key){const k=String(key);for(const store of [nativeStore,sessionStore]){if(store){try{const value=store.getItem(k);if(value!==null)return value;}catch(error){lastError=error;}}}return memory.has(k)?memory.get(k):null;},
    setItem(key,value){const k=String(key),v=String(value),local=write(nativeStore,k,v);write(sessionStore,k,v);memory.set(k,v);return local.ok;},
    writePersistent(key,value){return write(nativeStore,key,value);},
    writeSession(key,value){const result=write(sessionStore,key,value);memory.set(String(key),String(value));return result;},
    readPersistent(key){return read(nativeStore,key);},
    readSession(key){return read(sessionStore,key);},
    removeItem(key){const k=String(key);for(const store of [nativeStore,sessionStore]){if(store){try{store.removeItem(k);}catch(error){lastError=error;}}}memory.delete(k);},
    clear(){for(const store of [nativeStore,sessionStore]){if(store){try{store.clear();}catch(error){lastError=error;}}}memory.clear();},
    key(index){for(const store of [nativeStore,sessionStore]){if(store){try{const value=store.key(index);if(value!==null)return value;}catch(error){lastError=error;}}}return Array.from(memory.keys())[index]??null;},
    get length(){if(nativeStore){try{return nativeStore.length;}catch(error){lastError=error;}}if(sessionStore){try{return sessionStore.length;}catch(error){lastError=error;}}return memory.size;},
    isPersistent(){return !!nativeStore;},isSessionPersistent(){return !!sessionStore;},getLastError(){return lastError;}
  };
})();
