let cart=[],posCat='todo',posProc=false,posPayM='efectivo',modoMayorista=false;
const _NA_SEED_CATALOG_VERSION='20250922_xlsx';
const _NA_SEED_PRODUCTOS=JSON.parse(JSON.stringify(productos));
const _NA_APP_INITIALIZED_KEY='na_app_initialized_v1';
const _NA_SEED_VERSION_KEY='na_seed_catalog_version';
const _NA_SEED_SUPPRESSED_KEY='na_seed_catalog_suppressed';

function _naMarkCatalogState({seeded=false,suppressed=false}={}){
  storage.setItem(_NA_APP_INITIALIZED_KEY,'true');
  storage.setItem(_NA_SEED_SUPPRESSED_KEY,suppressed?'true':'false');
  if(seeded)storage.setItem(_NA_SEED_VERSION_KEY,_NA_SEED_CATALOG_VERSION);
}
function _naSeedIdentity(product){
  const sku=_naClean(product?.sku).toLowerCase(),barcode=_naClean(product?.barcode).toLowerCase();
  return{sku,barcode};
}
function _naMergeSeedCatalog(){
  if(!Array.isArray(productos))productos=[];
  const usedIds=new Set(productos.map(p=>String(p.id)));
  let nextId=Math.max(0,...productos.map(p=>Number(p.id)||0))+1,added=0;
  for(const source of _NA_SEED_PRODUCTOS){
    const seed=_naClone(source),identity=_naSeedIdentity(seed);
    const duplicate=productos.some(current=>{
      const other=_naSeedIdentity(current);
      return(identity.sku&&other.sku===identity.sku)||(identity.barcode&&other.barcode===identity.barcode);
    });
    if(duplicate)continue;
    if(usedIds.has(String(seed.id))){while(usedIds.has(String(nextId)))nextId++;seed.id=nextId++;}
    usedIds.add(String(seed.id));productos.push(seed);added++;
  }
  return added;
}
function _naApplySeedCatalog(force=false,hasPersistedState=false){
  const initialized=storage.getItem(_NA_APP_INITIALIZED_KEY)==='true';
  const suppressed=storage.getItem(_NA_SEED_SUPPRESSED_KEY)==='true';
  if(force){
    const added=_naMergeSeedCatalog();
    _naMarkCatalogState({seeded:true,suppressed:false});
    return added;
  }
  if(hasPersistedState){
    _naMarkCatalogState({seeded:false,suppressed:Array.isArray(productos)&&productos.length===0});
    return 0;
  }
  if(initialized||suppressed){
    productos=[];
    _naMarkCatalogState({seeded:false,suppressed:true});
    return 0;
  }
  productos=_naClone(_NA_SEED_PRODUCTOS);
  _naMarkCatalogState({seeded:true,suppressed:false});
  return productos.length;
}
async function cargarCatalogoInicial(){
  if(isModuleLocked('productos')||isModuleLocked('importacion')){toast('Desbloquea Productos e Importaciones antes de cargar el catálogo','error');return;}
  if(!_naAuthorize('importar','Cargar catálogo inicial'))return;
  const accepted=await _naConfirmAction(
    'Se agregarán únicamente los productos del catálogo inicial que todavía no existan. No se reemplazarán ni borrarán tus productos actuales.',
    {title:'Cargar catálogo inicial',subtitle:'La carga es manual y evita duplicados por SKU o código de barras.',icon:'📦',okText:'Agregar productos'}
  );
  if(!accepted)return;
  const backup=_naClone(productos),added=_naApplySeedCatalog(true,true);
  if(!added){toast('El catálogo inicial ya está incorporado; no se añadieron duplicados');return;}
  _naNormalizeData();invRender();posRender();cfgUpdateStats();updateDashboard();
  const persistResult=await saveAllData();
  if(!_naWasPersisted(persistResult)){
    productos=backup;await saveAllData();invRender();posRender();cfgUpdateStats();updateDashboard();
    toast('No se pudo guardar permanentemente la carga del catálogo inicial','error');return;
  }
  toast(`Catálogo inicial: ${added} producto${added===1?' agregado':'s agregados'}`,'success');
}


// ===== CATÁLOGO V1: normalización de nombres (MAYÚSCULAS + trim + espacio simple) =====
// Misma regla para alta, edición e importación (presente y futura). Se instala en
// DOMContentLoaded: inline-01 se parsea primero ⇒ su handler corre ANTES que el arranque
// de inline-03, envolviendo al WINNER vigente de guardarProd (inline-08→07→02) y de
// _naNormalizeData (inline-06→02, llamado por loadAllData, cargarCatalogoInicial y
// confirmProductImport antes de persistir). Solo transforma product.name: id, stock,
// precio, costo, ledger, historial de ventas e impuestos quedan intactos. Las 2535
// referencias externas NO entran al runtime; HIGH_CONFIDENCE queda solo como propuesta.
function _naNormCatalogName(value){
  return String(value??'').trim().replace(/\s+/g,' ').toUpperCase();
}
