const _NA_SCANNER_DEFAULTS={enabled:true,sound:true,minLength:4,maxIntervalMs:65};
const _naScannerState={buffer:'',times:[],resetTimer:null,statusTimer:null,lastCode:'',lastProcessedAt:0,audioContext:null};
