function _naScannerPageActive(){return document.getElementById('pagePOS')?.classList.contains('active');}
function _naScannerEditableTarget(target){return !!target&&(target.isContentEditable||['INPUT','TEXTAREA','SELECT'].includes(target.tagName));}
function _naScannerModalOpen(){return !!document.querySelector('.modal-overlay.open,.na-confirm-overlay.open')||document.body.classList.contains('security-session-locked');}
function _naScannerTimingLooksFast(code,times,cfg=_naScannerCfg()){
  if(String(code||'').length<Math.max(1,Number(cfg.minLength)||4)||!Array.isArray(times)||times.length<2)return false;
  const duration=Math.max(0,times[times.length-1]-times[0]),average=duration/Math.max(1,times.length-1);
  return average<=Math.max(20,Number(cfg.maxIntervalMs)||65);
}
function _naUpdateScannerIndicator(state='',message=''){
  const el=document.getElementById('scannerIndicator');if(!el)return;const cfg=_naScannerCfg(),label=el.querySelector('.scanner-label');
  clearTimeout(_naScannerState.statusTimer);
  if(!cfg.enabled){el.className='scanner-indicator disabled';if(label)label.textContent='Escáner desactivado';el.title='Activa la lectura automática desde Configuración';return;}
  const finalState=state||'ready',texts={ready:'Escáner listo',reading:'Leyendo…',success:'Código leído',error:'Lectura fallida'};
  el.className=`scanner-indicator ${finalState}`;if(label)label.textContent=message||texts[finalState]||texts.ready;el.title=message||texts[finalState]||texts.ready;
  if(['success','error'].includes(finalState))_naScannerState.statusTimer=setTimeout(()=>_naUpdateScannerIndicator('ready'),1500);
}
function _naResetScannerBuffer(updateStatus=true){clearTimeout(_naScannerState.resetTimer);_naScannerState.buffer='';_naScannerState.times=[];if(updateStatus)_naUpdateScannerIndicator('ready');}
function _naScannerBeep(ok=true){
  if(!_naScannerCfg().sound)return;
  try{const AudioCtx=window.AudioContext||window.webkitAudioContext;if(!AudioCtx)return;const ctx=_naScannerState.audioContext||new AudioCtx();_naScannerState.audioContext=ctx;if(ctx.state==='suspended')ctx.resume();const osc=ctx.createOscillator(),gain=ctx.createGain(),now=ctx.currentTime;osc.type='sine';osc.frequency.setValueAtTime(ok?880:220,now);gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(.08,now+.01);gain.gain.exponentialRampToValueAtTime(.0001,now+.11);osc.connect(gain);gain.connect(ctx.destination);osc.start(now);osc.stop(now+.12);}catch(error){console.debug('[Escáner] Audio no disponible');}
}
function _naOpenProductFromScannedCode(code){
  if(isModuleLocked('productos')){toast('El código no existe y el módulo de productos está bloqueado','error');return;}
  abrirModalProd();const barcode=document.getElementById('pBarcode');if(barcode)barcode.value=String(code).slice(0,160);setTimeout(()=>document.getElementById('pNombre')?.focus(),80);
}
async function _naProcessScannedCode(raw,{scanner=false}={}){
  const code=String(raw||'').trim().slice(0,160);if(!code)return;
  if(!scanner){posAddBySku(code);return;}
  const now=Date.now();if(_naScannerState.lastCode===code&&now-_naScannerState.lastProcessedAt<300){_naUpdateScannerIndicator('error','Lectura repetida');return;}
  _naScannerState.lastCode=code;_naScannerState.lastProcessedAt=now;
  const product=productos.find(p=>_naProductMatchesCode(p,code));
  if(product){
    if(_naTracksStock(product)&&_naNumber(product.stock)<=0&&!_naFreeSaleCfg().allowRegisteredNoStock){_naScannerBeep(false);_naUpdateScannerIndicator('error','Sin stock');toast(`${product.name} está sin stock`,'error');return;}
    posAdd(product.id);_naScannerBeep(true);_naUpdateScannerIndicator(_naNumber(product.stock)<=0?'error':'success',product.name);toast(`📷 ${product.name} agregado${_naNumber(product.stock)<=0?' sin stock':''}`,_naNumber(product.stock)<=0?'error':'success');return;
  }
  _naScannerBeep(false);_naUpdateScannerIndicator('error','Código no registrado');toast(`Código no encontrado: ${code}`,'error');
  const create=await _naConfirmAction(`Código leído: ${code}`,{title:'Producto no encontrado',subtitle:'Puedes registrarlo sin perder el código escaneado.',icon:'▥',okText:'Crear producto'});
  if(create)_naOpenProductFromScannedCode(code);
}
function _naInitBarcodeScanner(){
  const ps=document.getElementById('posSearch');if(!ps||ps.dataset.scannerReady==='true')return;ps.dataset.scannerReady='true';let filterTimer;
  ps.addEventListener('input',()=>{clearTimeout(filterTimer);filterTimer=setTimeout(()=>posFilter(),220);});
  document.addEventListener('keydown',async event=>{
    const cfg=_naScannerCfg();if(!cfg.enabled||!_naScannerPageActive()||securityIsLocked())return;
    const isSearch=event.target===ps;if(_naScannerModalOpen()||(_naScannerEditableTarget(event.target)&&!isSearch)){_naResetScannerBuffer(false);return;}
    if(event.ctrlKey||event.metaKey||event.altKey)return;
    if(event.key==='Enter'){
      const code=String(ps.value||_naScannerState.buffer).trim();if(!code)return;const scannerLike=_naScannerTimingLooksFast(code,_naScannerState.times,cfg);
      event.preventDefault();ps.value='';posRender();_naResetScannerBuffer(false);await _naProcessScannedCode(code,{scanner:scannerLike});return;
    }
    if(event.key.length!==1)return;
    const now=performance.now(),gap=_naScannerState.times.length?now-_naScannerState.times[_naScannerState.times.length-1]:Infinity,resetAfter=Math.max(180,Math.min(600,(Number(cfg.maxIntervalMs)||65)*4));
    if(!_naScannerState.buffer||gap>Math.max(120,(Number(cfg.maxIntervalMs)||65)*3)){_naScannerState.buffer=event.key;_naScannerState.times=[now];}else{_naScannerState.buffer+=event.key;_naScannerState.times.push(now);}
    if(!isSearch){event.preventDefault();ps.focus({preventScroll:true});ps.value+=event.key;ps.dispatchEvent(new Event('input',{bubbles:true}));}
    if(_naScannerState.buffer.length>=2)_naUpdateScannerIndicator('reading');
    clearTimeout(_naScannerState.resetTimer);_naScannerState.resetTimer=setTimeout(()=>_naResetScannerBuffer(),resetAfter);
  },true);
  _naUpdateScannerIndicator();
}
