// ===== POS — MENÚ 3 PUNTOS =====
function toggleCartMenu(){
  const dd=document.getElementById('cartMenuDropdown');if(!dd)return;
  dd.style.display=dd.style.display==='block'?'none':'block';
}
function closeCartMenu(){
  const dd=document.getElementById('cartMenuDropdown');if(dd)dd.style.display='none';
}
document.addEventListener('click',function(e){
  const dd=document.getElementById('cartMenuDropdown');
  const btn=document.getElementById('btnCartMenu');
  if(dd&&btn&&!btn.contains(e.target)&&!dd.contains(e.target))dd.style.display='none';
});

// ===== POS — DESCUENTO (respeta margen de ganancia) =====


function quitarDescuento(){
  cart.forEach(it=>{
    if(it._precioOriginal!=null){it.precio=it._precioOriginal;delete it._precioOriginal;delete it._descuento;}
  });
  posUpdateCart();
  const badge=document.getElementById('btnDescInfo');if(badge)badge.style.display='none';
  toast('Descuento removido');
}

// ===== POS — BORRADORES =====
function guardarBorrador(){
  if(!cart.length){toast('El carrito está vacío','error');return;}
  try{const serialized=JSON.stringify(cart),local=storage.writePersistent('na_cart_draft',serialized),session=storage.writeSession('na_cart_draft',serialized);if(local.ok&&local.verified)toast('💾 Borrador guardado','success');else if(session.ok&&session.verified)toast('Borrador disponible solo mientras esta pestaña permanezca abierta','error');else toast('No se pudo guardar el borrador','error');}
  catch(error){console.error('[Persistencia] No se pudo preparar el borrador:',error?.name||'Error');toast('No se pudo guardar el borrador','error');}
  closeCartMenu();
}

async function limpiarCarrito(){
  if(!cart.length){toast('El carrito ya está vacío');return;}
  const accepted=await _naConfirmAction('¿Vaciar todo el carrito?',{title:'Limpiar carrito',subtitle:'Se eliminarán los productos agregados a la venta actual.',icon:'🧹',okText:'Sí, limpiar'});
  if(!accepted)return;
  cart=[];
  const badge=document.getElementById('btnDescInfo');if(badge)badge.style.display='none';
  posUpdateCart();toast('🧹 Carrito limpiado');closeCartMenu();
}

