function _baseInvRender(){invBadges();const s=sinTildes(document.getElementById('invSearch').value.toLowerCase());const cat=document.getElementById('invCat').value;const list=productos.filter(p=>{const ms=sinTildes(p.name.toLowerCase()).includes(s)||sinTildes(p.descripcion||'').includes(s)||sinTildes(p.marca||'').includes(s)||p.sku.toLowerCase().includes(s)||(p.barcode||'').includes(s)||_naProductAltCodes(p).some(code=>code.toLowerCase().includes(s));const mc=!cat||p.cat===cat;let mt=true;if(invTab==='critico')mt=_naTracksStock(p)&&p.stock<=p.stockMin;if(invTab==='vencimiento'){const d=diasHasta(p.venc);mt=d!==null&&d>=0&&d<=30;}if(invTab==='vencidos'){const d=diasHasta(p.venc);mt=d!==null&&d<0;}return ms&&mc&&mt;});const body=document.getElementById('invBody');if(!list.length){body.innerHTML='<tr><td colspan="6"><div class="empty-state"><div class="ei">🔍</div><p>Sin productos</p></div></td></tr>';return;}body.innerHTML=list.map(p=>{const safeImage=typeof _naProductImageSource==='function'?_naProductImageSource(p):null,tracked=_naTracksStock(p),sc=!tracked?'ok':p.stock<=0?'out':p.stock<=p.stockMin?'low':'ok';const sl=!tracked?'∞ Sin control':p.stock<0?`✕ Faltan ${Math.abs(p.stock)}`:p.stock===0?'✕ Sin stock':p.stock<=p.stockMin?`⚠ ${p.stock}`:`✓ ${p.stock}`;const d=diasHasta(p.venc);const vc=!p.venc?'na':d<0?'vencido':d<=30?'pronto':'ok';const vl=!p.venc?'—':d<0?'Vencido':d===0?'Hoy':d<=30?`${d}d`:p.venc;return`<tr><td><div class="prod-info"><div class="prod-icon-sm">${safeImage?`<img src="${safeImage}" loading="lazy" decoding="async" style="width:100%;height:100%;object-fit:cover;border-radius:8px">`:p.icon}</div><div><div class="prod-name-sm">${p.name}</div><div class="prod-sku-sm">${p.sku}${p.marca&&p.marca!=='Sin marca'?` · ${p.marca}`:''} · ${_naCategoryTitle(p.unidad||'unidad')}</div></div></div></td><td><span class="cat-pill">${_naCategoryLabel(p.cat)}</span></td><td><div style="font-size:12px;font-weight:800;color:var(--teal)">S/ ${p.precio.toFixed(2)}</div><div style="font-size:10px;color:var(--slate)">Costo: S/ ${p.costo.toFixed(2)}</div></td><td><span class="venc-pill ${vc}">${vl}</span></td><td><span class="stock-pill ${sc}">${sl}</span></td><td><div class="act-btns">${tracked?`<button class="btn-act btn-ent" onclick="abrirMovInv(${p.id},'entrada')">📥</button><button class="btn-act btn-sal" onclick="abrirMovInv(${p.id},'salida')">📤</button>`:'<button class="btn-act" title="Sin control de inventario">∞</button>'}<button class="btn-act btn-edt" onclick="editProd(${p.id})">✏️</button></div></td></tr>`;}).join('');}

const NA_MAX_ALT_BARCODES=10;
function _naNormalizeAltCodes(value,legacy=''){
  const raw=[];
  if(Array.isArray(value))raw.push(...value);
  else if(value!=null&&String(value).trim())raw.push(...String(value).split(/[\n,;|]+/));
  if(legacy!=null&&String(legacy).trim())raw.push(legacy);
  const seen=new Set(),result=[];
  for(const item of raw){const code=_naClean(item);const key=code.toLowerCase();if(!code||seen.has(key))continue;seen.add(key);result.push(code);if(result.length>=NA_MAX_ALT_BARCODES)break;}
  return result;
}
function _naProductAltCodes(product){return _naNormalizeAltCodes(product?.codigosAlternativos,product?.codigoAlternativo);}
function _naCurrentAltFieldValues(){return [...document.querySelectorAll('#pAltCodesList .alt-code-input')].map(input=>input.value);}
function _naAltBarcodeRow(code='',index=0){
  return `<div class="alt-code-row"><span class="alt-code-number">${index+1}</span><input class="fi alt-code-input" inputmode="numeric" autocomplete="off" value="${_naEsc(String(code??''))}" placeholder="Código alternativo ${index+1}" oninput="_naUpdateAltBarcodeUI()"><button type="button" class="alt-code-remove" title="Quitar código" aria-label="Quitar código alternativo ${index+1}" onclick="removeAltBarcodeField(this)">×</button></div>`;
}
function _naUpdateAltBarcodeUI(){
  const inputs=[...document.querySelectorAll('#pAltCodesList .alt-code-input')],count=document.getElementById('pAltCodeCount'),add=document.getElementById('pAddAltCodeBtn');
  // V2A: el contador refleja el total de códigos del producto (principal + alternativos con valor).
  const primary=_naClean(document.getElementById('pBarcode')?.value);
  const used=inputs.filter(input=>String(input.value||'').trim()).length+(primary?1:0);
  if(count)count.textContent=`${used}/${NA_MAX_TOTAL_CODES}`;
  if(add){
    const atLimit=used>=NA_MAX_TOTAL_CODES||inputs.length>=NA_MAX_ALT_BARCODES;
    add.disabled=atLimit;
    add.textContent=atLimit?'Límite de 7 códigos alcanzado':'＋ Añadir otro código de barras';
  }
  inputs.forEach((input,index)=>{
    input.placeholder=`Código alternativo ${index+1}`;
    const row=input.closest('.alt-code-row'),number=row?.querySelector('.alt-code-number'),remove=row?.querySelector('.alt-code-remove');
    if(number)number.textContent=String(index+1);
    if(remove){remove.disabled=inputs.length===1;remove.setAttribute('aria-label',`Quitar código alternativo ${index+1}`);}
  });
}
function renderAltBarcodeFields(codes=[]){
  const wrap=document.getElementById('pAltCodesList');if(!wrap)return;
  let values;
  if(Array.isArray(codes))values=codes.slice(0,NA_MAX_ALT_BARCODES).map(code=>String(code??''));
  else values=_naNormalizeAltCodes(codes);
  if(!values.length)values=[''];
  wrap.innerHTML=values.map((code,index)=>_naAltBarcodeRow(code,index)).join('');
  _naUpdateAltBarcodeUI();
}
function addAltBarcodeField(value=''){
  const wrap=document.getElementById('pAltCodesList');if(!wrap){toast('No se encontró la sección de códigos alternativos','error');return;}
  const current=_naCurrentAltFieldValues();
  // V2A: tope de escritura nueva = 7 códigos totales (1 principal + 6 alternativos).
  const primary=_naClean(document.getElementById('pBarcode')?.value);
  const used=current.filter(code=>String(code).trim()).length+(primary?1:0);
  if(used>=NA_MAX_TOTAL_CODES){toast('Cada producto admite 7 códigos en total: 1 principal + 6 alternativos','error');return;}
  if(current.length>=NA_MAX_ALT_BARCODES){toast('Puedes registrar como máximo 10 códigos alternativos','error');return;}
  current.push(String(value??''));
  renderAltBarcodeFields(current);
  requestAnimationFrame(()=>{
    const inputs=[...document.querySelectorAll('#pAltCodesList .alt-code-input')];
    const newest=inputs[inputs.length-1];
    newest?.focus();
    newest?.scrollIntoView?.({behavior:'smooth',block:'center'});
  });
}
function removeAltBarcodeField(button){
  const rows=[...document.querySelectorAll('#pAltCodesList .alt-code-row')],row=button?.closest?.('.alt-code-row'),index=rows.indexOf(row),values=_naCurrentAltFieldValues();
  if(index>=0)values.splice(index,1);
  if(!values.length)values.push('');
  renderAltBarcodeFields(values);
}
window.addAltBarcodeField=addAltBarcodeField;
window.removeAltBarcodeField=removeAltBarcodeField;
window._naUpdateAltBarcodeUI=_naUpdateAltBarcodeUI;
function readAltBarcodes(){
  const values=_naCurrentAltFieldValues().map(_naClean).filter(Boolean),seen=new Set(),codes=[];
  for(const code of values){const key=code.toLowerCase();if(seen.has(key)){toast(`El código alternativo ${code} está repetido`,'error');return null;}seen.add(key);codes.push(code);}
  return codes.slice(0,NA_MAX_ALT_BARCODES);
}
function _naAllProductCodes(product){return [product?.sku,product?.barcode,..._naProductAltCodes(product)].map(_naClean).filter(Boolean);}
function _naFindCodeOwner(code,excludedId=null){const key=_naClean(code).toLowerCase();if(!key)return null;return productos.find(product=>String(product.id)!==String(excludedId)&&_naAllProductCodes(product).some(existing=>existing.toLowerCase()===key))||null;}
function _naProductMatchesCode(product,code){const key=_naClean(code).toLowerCase();return !!key&&_naAllProductCodes(product).some(existing=>existing.toLowerCase()===key);}

// ===== CATÁLOGO V2A — NÚCLEO DE CÓDIGOS DE BARRAS (1 principal + 6 alternativos) =====
// Tope de ESCRITURA nueva: 7 códigos totales por producto. La tolerancia de LECTURA,
// normalización y respaldo se mantiene en 10 alternativos (NA_MAX_ALT_BARCODES) para que
// los datos/respaldos legacy con más de 7 sigan siendo legibles, buscables y restaurables.
// Los códigos históricos nunca se eliminan automáticamente: cambiar el principal conserva
// el anterior como alternativo (A→B→C→A sin pérdida ni duplicados).
const NA_MAX_TOTAL_CODES=7;
const NA_MAX_ALT_CODES_NEW=NA_MAX_TOTAL_CODES-1;
function _naProductByCode(code){
  const key=_naClean(code).toLowerCase();
  if(!key)return null;
  return productos.find(product=>_naProductMatchesCode(product,key))||null;
}
function _naProductCodeCount(product){
  if(!product)return 0;
  return (_naClean(product.barcode)?1:0)+_naProductAltCodes(product).length;
}
function _naAddProductCode(product,code){
  if(!product||typeof product!=='object')return{ok:false,reason:'INVALID'};
  const clean=_naClean(code);
  if(!clean)return{ok:false,reason:'INVALID'};
  const key=clean.toLowerCase();
  if(_naAllProductCodes(product).some(existing=>existing.toLowerCase()===key))return{ok:false,reason:'DUPLICATE_SAME_PRODUCT'};
  const owner=_naFindCodeOwner(clean,product.id);
  if(owner)return{ok:false,reason:'FOREIGN_OWNER',owner};
  if(_naProductCodeCount(product)>=NA_MAX_TOTAL_CODES)return{ok:false,reason:'CAP_7'};
  product.codigosAlternativos=[..._naProductAltCodes(product),clean];
  product.codigoAlternativo=product.codigosAlternativos[0]||'';
  return{ok:true,codes:_naAllProductCodes(product)};
}
function _naSetPrincipalCode(product,code){
  if(!product||typeof product!=='object')return{ok:false,reason:'INVALID'};
  const clean=_naClean(code);
  if(!clean)return{ok:false,reason:'INVALID'};
  const key=clean.toLowerCase();
  if(_naClean(product.sku).toLowerCase()===key)return{ok:false,reason:'DUPLICATE_SAME_PRODUCT'};
  const owner=_naFindCodeOwner(clean,product.id);
  if(owner)return{ok:false,reason:'FOREIGN_OWNER',owner};
  const prevPrimary=_naClean(product.barcode);
  const seen=new Set([key]),nextAlts=[];
  const push=c=>{const k=c.toLowerCase();if(!seen.has(k)){seen.add(k);nextAlts.push(c);}};
  if(prevPrimary&&prevPrimary.toLowerCase()!==key)push(prevPrimary);
  _naProductAltCodes(product).forEach(c=>{if(c.toLowerCase()!==key)push(c);});
  if(nextAlts.length>NA_MAX_ALT_BARCODES)return{ok:false,reason:'CAP_ABSOLUTE'};
  product.barcode=clean;
  product.codigosAlternativos=nextAlts;
  product.codigoAlternativo=nextAlts[0]||'';
  return{ok:true};
}
function _naRemoveProductCode(product,code){
  if(!product||typeof product!=='object')return{ok:false,reason:'INVALID'};
  const clean=_naClean(code);
  if(!clean)return{ok:false,reason:'INVALID'};
  const key=clean.toLowerCase();
  if(_naClean(product.barcode).toLowerCase()===key)return{ok:false,reason:'PRIMARY'};
  const alts=_naProductAltCodes(product);
  if(!alts.some(c=>c.toLowerCase()===key))return{ok:false,reason:'NOT_FOUND'};
  const next=alts.filter(c=>c.toLowerCase()!==key);
  product.codigosAlternativos=next;
  product.codigoAlternativo=next[0]||'';
  return{ok:true};
}

