let _naClosingCashExpected=null;
function _naRefreshClosingCashTotals(t){
  _naClosingCashExpected=t.ef;
  document.getElementById('cierreBox').innerHTML=`<div class="cc-row"><span>Ventas del día</span><span class="ccv">${fmt(t.ven)}</span></div><div class="cc-row"><span>Egresos totales</span><span class="ccv">${fmt(t.egr)}</span></div><div class="cc-row hl"><span>💰 Efectivo esperado</span><span class="ccv">${fmt(t.ef)}</span></div>`;
  if(document.getElementById('cajContado').value!=='')calcDif();
}
function prepCierre(){
  if(!cajEstado.abierta||cajEstado.cerrada){toast('La caja ya está cerrada','error');return;}
  document.getElementById('cajContado').value='';
  _naRefreshClosingCashTotals(cajTotales());
  document.getElementById('difBanner').style.display='none';
  document.getElementById('mCierre').classList.add('open');
}
function calcDif(){if(_naClosingCashExpected===null)_naClosingCashExpected=cajTotales().ef;const cont=parseFloat(document.getElementById('cajContado').value)||0,dif=cont-_naClosingCashExpected;const b=document.getElementById('difBanner');b.style.display='block';if(Math.abs(dif)<0.01){b.style.cssText='background:var(--green-light);border:1px solid #bbf7d0;border-radius:9px;padding:10px 13px;margin-bottom:13px;display:block;text-align:center';document.getElementById('difLbl').textContent='✅ Cuadra perfectamente';document.getElementById('difVal').textContent='Sin diferencia';}else if(dif>0){b.style.cssText='background:var(--amber-light);border:1px solid #fcd34d;border-radius:9px;padding:10px 13px;margin-bottom:13px;display:block;text-align:center';document.getElementById('difLbl').textContent='⚠ Sobrante en caja';document.getElementById('difVal').textContent=`+${fmt(dif)}`;}else{b.style.cssText='background:var(--red-light);border:1px solid #fca5a5;border-radius:9px;padding:10px 13px;margin-bottom:13px;display:block;text-align:center';document.getElementById('difLbl').textContent='🔴 Faltante en caja';document.getElementById('difVal').textContent=fmt(dif);}}


// ===== VENTAS =====
let ventas=[];
const totalV=v=>Number((Array.isArray(v?.items)?v.items:[]).reduce((a,i)=>a+_naNumber(i.precio??i.precioUnitario)*_naNumber(i.qty??i.cantidad),0).toFixed(2));let ventasTab='hoy';const mpCls={efectivo:'mp-ef',yape:'mp-yp',credito:'mp-cr',transferencia:'mp-tr',mixto:'mp-tr'};const mpLbl={efectivo:'💵 Efectivo',yape:'📲 Yape',credito:'📋 Crédito',transferencia:'🏦 Transf.',mixto:'🔀 Mixto'};
function ventasSetTab(btn,tab){document.querySelectorAll('#pageVentas .tab').forEach(t=>t.classList.remove('active'));btn.classList.add('active');ventasTab=tab;ventasRender();}
function ventasFiltradas(){const s=sinTildes(document.getElementById('ventasSearch').value.toLowerCase()),m=document.getElementById('ventasMetodo').value;const LUNES=getLunesSemana();return ventas.filter(v=>{let mt=true;if(ventasTab==='hoy')mt=v.fecha===obtenerHoy();else if(ventasTab==='semana')mt=v.fecha>=LUNES&&v.fecha<=obtenerHoy();const ms=_naSaleMatchesSearch(v,s);return mt&&ms&&(!m||v.metodo===m);});}

function _baseVentasRender(){
    const g=calcularGanancias();const list=ventasTab==='historial'?ventas.filter(v=>{const s=sinTildes(document.getElementById('ventasSearch').value.toLowerCase()),m=document.getElementById('ventasMetodo').value;return _naSaleMatchesSearch(v,s)&&(!m||v.metodo===m);}):ventasFiltradas();
    const act=list.filter(v=>!v.anulada);const tv=act.reduce((a,v)=>a+totalV(v),0),tu=act.reduce((a,v)=>a+v.items.reduce((b,i)=>b+_naUnitsSold(i),0),0),tp=act.length?tv/act.length:0;
    document.getElementById('ventasKPI').innerHTML=`<div class="vkpi teal"><div class="vkpi-val">${fmt(g.gananciaBruta)}</div><div class="vkpi-lbl">Ganancia bruta</div></div><div class="vkpi green"><div class="vkpi-val">${fmt(g.margenReal)}</div><div class="vkpi-lbl">Margen real</div></div><div class="vkpi amber"><div class="vkpi-val">${fmt(g.gastosHoy)}</div><div class="vkpi-lbl">Gastos</div></div><div class="vkpi purple"><div class="vkpi-val">${fmt(g.gananciaNeta)}</div><div class="vkpi-lbl">Ganancia neta</div></div>`;
    const mc=document.getElementById('ventasContent');
    if(ventasTab==='productos'){const cnt={};ventas.filter(v=>!v.anulada).forEach(v=>v.items.forEach(i=>{const k=String(i.id??i.sku??i.name);if(!cnt[k])cnt[k]={icon:i.icon,name:i.name,qty:0,total:0};cnt[k].qty+=_naUnitsSold(i);cnt[k].total+=i.precio*i.qty;}));const top=Object.values(cnt).sort((a,b)=>b.total-a.total).slice(0,6);const mxT=top[0]?.total||1;mc.innerHTML=`<div class="v-chart"><div class="v-chart-title">🏆 Top 6 productos</div><div class="bars">${top.map(p=>`<div class="bar-col"><div class="bar-v">${fmtS(p.total)}</div><div class="bar" style="height:${Math.max(4,(p.total/mxT)*65)}px"></div><div class="bar-lbl">${p.icon}</div></div>`).join('')}</div></div><div class="v-list-wrap">${top.map((p,i)=>`<div class="venta-card"><div class="v-header"><div class="v-num">${i+1}</div><div class="v-info"><div class="v-items-txt">${p.icon} ${p.name}</div><div class="v-meta"><span>${p.qty} unidades vendidas</span></div></div><div class="v-right"><div class="v-total">${fmt(p.total)}</div></div></div></div>`).join('')}</div>`;return;}
    let html='';if(!list.length){mc.innerHTML=html+`<div class="empty-state"><div class="ei">📊</div><p>Sin ventas en este período</p></div>`;return;}
    html+=`<div class="v-list-wrap">${list.map(v=>`<div class="venta-card${v.anulada?' anulada':''}"><div class="v-header" onclick="toggleVDet('${v.id}')"><div class="v-num">${v.id.replace('V-','#')}</div><div class="v-info"><div class="v-items-txt">${v.anulada?'<span class="badge-anulada">ANULADA</span> ':''}${v.items.map(i=>`${i.ventaLibre?'<span class="sale-special-badge free">VARIOS</span> ':i.ventaSinStock?'<span class="sale-special-badge shortage">SIN STOCK</span> ':''}${i.qty>1?i.qty+'x ':''}${_naEsc(i.name)}`).join(', ')}</div><div class="v-meta"><span>${_naEsc(v.fecha)} ${_naEsc(v.hora24||v.hora||'')}</span><span>👤 ${_naEsc(v.cajeroNombre||v.cajero||'Cajero')}${v.cajeroId?' · '+_naEsc(v.cajeroId):''}</span><span class="sale-state-badge ${v.anulada?'cancelled':v.estado==='credito'?'credit':'completed'}">${_naEsc(_naSaleStateLabel(v))}</span><span class="sale-type-badge">${_naEsc(_naSaleTypeLabel(v))}</span></div></div><div class="v-right"><div class="v-total">${v.anulada?'—':fmt(totalV(v))}</div><span class="mp ${mpCls[v.metodo]||'mp-ef'}">${mpLbl[v.metodo]||v.metodo}</span></div></div><div class="v-detalle" id="vd-${v.id}">${v.items.map(i=>`<div class="det-row"><span style="font-weight:700">${_naEsc(i.icon||'📦')} ${_naEsc(i.name)} ${i.ventaLibre?'<span class="sale-special-badge free">VARIOS</span>':i.ventaSinStock?'<span class="sale-special-badge shortage">SIN STOCK</span>':''} <span style="color:var(--slate);font-size:11px">x${i.qty}</span></span><span class="det-price">${fmt(i.precio*i.qty)}</span></div>`).join('')}<div class="det-row"><span>Total</span><span style="color:var(--teal)">${fmt(totalV(v))}</span></div><div class="sale-audit-grid"><div><span>Estado</span><strong>${_naEsc(_naSaleStateLabel(v))}</strong></div><div><span>Tipo de venta</span><strong>${_naEsc(_naSaleTypeLabel(v))}</strong></div><div><span>Cajero</span><strong>${_naEsc(v.cajeroNombre||v.cajero||'Cajero')}${v.cajeroId?' · '+_naEsc(v.cajeroId):''}</strong></div><div><span>Cliente</span><strong>${_naEsc(v.clienteNombre||'Consumidor final')}</strong></div><div><span>Fecha y hora</span><strong>${_naEsc(v.fecha)} · ${_naEsc(v.hora24||v.hora||'')}</strong></div><div><span>Operación</span><strong>${_naEsc(v.paymentRef||v.operation||'-')}</strong></div><div><span>Líneas / unidades</span><strong>${_naInt(v.cantidadLineas,v.items.length)} / ${_naNumber(v.unidadesFisicas,v.items.reduce((s,i)=>s+_naUnitsSold(i),0))}</strong></div><div><span>Método</span><strong>${_naEsc(mpLbl[v.metodo]||v.metodo||'Efectivo')}</strong></div></div>${v.metodo==='mixto'&&v.paymentBreakdown?`<div class="det-row"><span>💵 Efectivo</span><span>${fmt(v.paymentBreakdown.efectivo)}</span></div><div class="det-row"><span>${v.paymentBreakdown.digitalMethod==='yape'?'📱 Yape/Plin':'🏦 Transferencia'}</span><span>${fmt(v.paymentBreakdown.digital)}</span></div>`:''}<div class="det-acts"><button class="btn-det btn-reimp" onclick="verTicket('${v.id}')">🧾 Ticket</button>${!v.anulada?`<button class="btn-det btn-anul" onclick="anularV('${v.id}')">🚫 Anular</button>`:'<span style="font-size:11px;color:var(--red);font-weight:700">Anulada</span>'}</div></div></div>`).join('')}</div>`;mc.innerHTML=html;
}
function toggleVDet(id){document.getElementById(`vd-${id}`).classList.toggle('open');}


